  'autonomy.title': 'How much {name} does alone',
  'autonomy.intro': 'Your choice, from day one. Whatever you choose: no order is confirmed without you, prices only come from your price rules, and anything your rules hold still waits for you.',
  'autonomy.disclosure': 'One thing to know before you choose: when {name} replies without you, the first message in a conversation tells your customer they are not talking to a person, and offers them someone from your team. A reply you send yourself carries no such line — you sent it.',
  'autonomy.needsName': 'Whatever you choose here, every reply keeps coming to you first until you confirm the name in Getting ready — a message sent without you gives your customer that name, and you should read it first.',
  'autonomy.notReleased': 'Not yet available. The line that tells a customer they are not talking to a person has not been read by a native speaker of every language used, and nothing goes out without you until it has.',
  'autonomy.languages': '{name} sends alone only to customers writing in {ready}. Replies to customers writing in {waiting}, or in any other language, wait for you until a native speaker has read the line that says who is answering.',
  'autonomy.flash.notReleased': 'Not yet — the line that tells a customer they are not talking to a person is still being checked in every language used.',
  'autonomy.flash.notEarned': 'Not yet: in a workspace that signed itself up, sending alone opens once it has been earned. Every reply waits for you until then.',
  'autonomy.notEarned.title': 'Replies wait for you for now.',
  'autonomy.notEarned.body': 'In a workspace that signed itself up, {name} sends alone only once that has been earned with your own customers. Until then, nothing goes out without you.',
