  'ramp.intro': 'Sending alone opens in two steps, from the replies decided for real customers. Your own test messages, once marked as yours, count toward nothing.',
  'ramp.talks': '{done} of the last {of} replies sent as written ({need} needed), from {customers} of {customersNeed} customers, over {days} of {daysNeed} days.',
  'ramp.talks.earned': 'Earned on {date}: replies without a price may go out alone.',
  'ramp.talks.flagged': 'One of these replies was stopped by a check before it went out; this step waits until it is no longer among the replies counted.',
