  'site.channels.email.how': 'From your business’s own mailbox.',
  'site.who.title': 'Who it is for',
  'site.who.body': 'Any business that sells or talks to customers over social media and e-mail — clothing and beauty brands, online stores, startups, agencies and services, as well as makers, exporters and wholesalers.',
  'site.who.languages': 'Your workspace is in English, Chinese, Arabic or Spanish.',
  'site.first.title': 'The first workspaces',
  'site.first.invite': 'Nomi opens to a small group first, by invitation, a few businesses at a time.',
  'site.first.drafts': 'At first, every reply waits for you. Sending on its own opens only once your assistant has earned it with your own customers.',
  'site.first.assisted': 'We read every new workspace, and help you set up where you need it.',
