  'legal.privacy.title': '隐私说明',
  'legal.privacy.intro': 'Nomi 是商家用来回复 Instagram、Facebook Messenger、WhatsApp 和邮件来信的助手。这一页说明：你写信给使用 Nomi 的商家时，会保存什么、为什么保存、以及怎样删除。',
  'legal.privacy.kept.title': '保存什么',
