  'refused.do.channel_cannot_initiate': 'يمكن انتظار الرسالة الأولى من الطرف الآخر، أو فتح صفحة الاتصالات للاطّلاع على ما تسمح به كل طريقة.',
  'refused.what.outreach_not_enabled': 'لم تُرسَل رسالة أولى إلى هذا الشخص.',
  'refused.why.outreach_not_enabled': 'لا إذن منك بعد بالمبادرة عبر هذه الطريقة.',
  'refused.do.outreach_not_enabled': 'يمكن التشغيل من صفحة الاتصالات عند الاستعداد.',
  'refused.what.suppressed': 'لم يُرسَل شيء إلى هذا الشخص.',
  'refused.why.suppressed': 'طُلب إيقاف المراسلة، وهذا الطلب لا ينتهي بمرور الوقت.',
  'refused.do.suppressed': 'لا مراسلة بعد الآن — لكن إن وصلت رسالة من هذا الشخص، فسيأتي ردّ من {name}.',
  'refused.what.no_consent': 'لم تُرسَل رسالة أولى إلى هذا الشخص.',
  'refused.why.no_consent': 'لا يوجد في السجل ما يقول إن ذلك جائز.',
  'refused.do.no_consent': 'يمكن إضافة مناسبة التعارف في جهات الاتصال، ثم إعادة الإرسال.',
  'refused.what.outreach_ceiling': 'توقّفت المبادرة بالكتابة لهذا اليوم.',
  'refused.why.outreach_ceiling': 'للمبادرات اليومية حدّ أقصى محدَّد منك، وقد استُنفد.',
  'refused.do.outreach_ceiling': 'يعود غدًا، والردّ مستمر على كل من يراسلك.',
  'outreach.title': 'المبادرة بالكتابة',
