  'conv.deletion.title': 'Eliminar los datos de tu cliente',
  'conv.deletion.lead': 'Cuando tu cliente pide en un mensaje que se eliminen sus datos, la solicitud suele anotarse aquí en cuanto llega, para que tú decidas. Si lo pide de otra forma, regístralo aquí. Quien opera Nomi la lleva a cabo a mano en un plazo de 30 días, y aquí aparece cuando se completa.',
