  'conv.deletion.ask': 'Pedir que se eliminen los datos de tu cliente',
  'conv.deletion.erased': 'Se elimina: quién es en cada canal, cada mensaje que envió o recibió, las respuestas y los precios preparados para esa persona y cualquier solicitud de muestra, las notas sobre sus conversaciones y las propias conversaciones, salvo lo que necesite un pedido.',
  'conv.deletion.kept': 'Se conserva: los pedidos que hizo, sin sus datos de contacto ni sus mensajes; si pidió que no se le escribiera, una nota de esa dirección para que nunca se le vuelva a escribir; y el registro de esta solicitud.',
  'conv.deletion.tell': 'Cuando se complete, aparecerá aquí y en Tus datos. Avísale entonces a tu cliente — Nomi no le escribe sobre esto.',
