  'site.hero.lead': 'Con Nomi tienes tu asistente, con el nombre que tú elijas. Cuando alguien te escribe por WhatsApp, Instagram, Messenger o correo, tu asistente prepara la respuesta con tus propios productos y precios, y tú la apruebas.',
